def f(I):
    H,W=len(I),len(I[0]); seen=[[False]*W for _ in range(H)]; 
    from collections import deque
    d=deque()
    for r in range(H):
        for c in range(W):
            if I[r][c]==1 and (r in (0,H-1) or c in (0,W-1)) and not seen[r][c]:
                seen[r][c]=True; d.append((r,c))
    while d:
        r,c=d.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and I[nr][nc]==1:
                seen[nr][nc]=True; d.append((nr,nc))
    return [[3 if x==1 and not seen[r][c] else x for c,x in enumerate(row)] for r,row in enumerate(I)]
